CREATE TABLE Logger (	LoggerID INT AUTO_INCREMENT PRIMARY KEY,    Forename VARCHAR(50) NOT NULL,    Surname VARCHAR(50) NOT NULL,    Email VARCHAR(50) NOT NULL UNIQUE);CREATE TABLE Location (  LocationID INT AUTO_INCREMENT PRIMARY KEY,  Country Varchar(50) NOT NULL,  Latitude DECIMAl(9,6) NOT NULL,  Longitude DECIMAL(9,6) NOT NULL);CREATE TABLE Evidence (	EvidenceID INT AUTO_INCREMENT PRIMARY KEY,    EvidenceType VARCHAR(50) NOT NULL,    Description VARCHAR(250) NOT NULL);CREATE TABLE Species (	SpeciesID INT AUTO_INCREMENT PRIMARY KEY,	Name VARCHAR(50) NOT NULL,    Status ENUM('Low', 'Medium', 'High') NOT NULL);CREATE TABLE Report (	ReportID INT AUTO_INCREMENT PRIMARY KEY,    LoggerID INT,    LocationID INT,    EvidenceID INT,    ReportDate DATE NOT NULL,    ReportDescription VARCHAR(250) NOT NULL,    FOREIGN KEY(LoggerID)	REFERENCES Logger(LoggerID),    FOREIGN KEY (LocationID)    REFERENCES Location(LocationID),    FOREIGN KEY (EvidenceID)    REFERENCES Evidence(EvidenceID));